function initialState(){if(WORKSPACE==="demo")return KontextModel.migrate(structuredClone(seed));const self={...structuredClone(seed.people[0]),projects:[]};return KontextModel.migrate({schema:1,hierarchyVersion:1,projects:[],people:[self],objects:[],tasks:[],goals:[],events:[],nextNumber:1});}
